import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ModalController, NavParams } from '@ionic/angular';
import { AuthenticationService } from 'src/app/services/authentication.service';
import { EmisService } from 'src/app/services/emis/emis.service';
import { IonicStorageService } from 'src/app/services/ionic-storage/ionic-storage.service';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { Storage } from '@ionic/storage';
import { DataService } from 'src/app/services/data.service';
import { UserSession } from 'src/app/models/usersession';
import jwt_decode from "jwt-decode";
import jwtDecode from 'jwt-decode';


@Component({
  selector: 'app-switch-user',
  templateUrl: './switch-user.page.html',
  styleUrls: ['./switch-user.page.scss'],
})
export class SwitchUserPage implements OnInit {
  userList: any;
  teacher_id: any;
  token: any;
  sessionData = new UserSession();
  errorMess: any;

  
  constructor(private modalCtrl: ModalController, 
    private navParams: NavParams, 
    private userSessionService: UserSessionService,
    private auth: AuthenticationService, 
    private router: Router, 
    public activeRoute: ActivatedRoute, 
    private sqliteDB: SqlitedatabaseService,
    private emisService: EmisService, 
    private ionicstorage: IonicStorageService, 
    private ionicStorage:Storage, 
    private dataService: DataService,) {
    this.userList = this.navParams.get('schoolClassData');
    this.teacher_id = this.userSessionService.teacher_id();
  }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.ionicstorage.getData('userInfo').then(
      (dataa) => {
        this.token = dataa.token;
        console.log(this.token);

      },
      (error) => console.error(error)
    );
  }

  clearCachedMenu() {
    this.dataService.clearCache();
  }

  closeModal() {
    this.modalCtrl.dismiss();
  }


  switchUser(userid) {
    console.log(userid);

    var data = {
      'records': {
        'emis_username': userid,
        'token': this.token
      }
    }

    let userName = window.localStorage.getItem('username');
    let password = window.localStorage.getItem('password');
    window.localStorage.clear();
    this.sqliteDB.removeDatabase();
    this.userSessionService.destroy();
    window.localStorage.setItem('username', userName);
    window.localStorage.setItem('password', password);
    this.router.navigate(['/login']);

    this.ionicStorage.forEach((value, key, index) => {
      if (key != "studentListBy_school_id" && key != "teacherListBy_school_id" && key != "currentSchool_id" && key != "learning_outcome" && key != 'store_observation' && key != 'learningOutcomeQues' && key != 'schoolListBy_District_id' && key != 'observation_list') {
        this.ionicStorage.remove(key)
        console.log("r", key);
      }
    })

    this.auth.validateAttendance(data,2);
    this.closeModal();
  }

}
